const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

// URL pública del webhook tal como está configurada en Twilio.
// Se toma de una variable de n8n (Settings > Variables), nunca hardcodeada acá:
// cambia con cada túnel de ngrok / dominio.
const webhookUrl = $vars.TWILIO_WEBHOOK_URL || '';
const authToken = $vars.TWILIO_AUTH_TOKEN || '';
const signature = headers['x-twilio-signature'] || headers['X-Twilio-Signature'] || '';

function validarFirma(url, params, sig, token) {
  if (!sig || !token || !url) return false;
  const keys = Object.keys(params).sort();
  let data = url;
  for (const k of keys) data += k + params[k];
  const hmac = crypto.createHmac('sha1', token).update(Buffer.from(data, 'utf-8')).digest('base64');
  const a = Buffer.from(hmac);
  const b = Buffer.from(sig);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

const firmaValida = validarFirma(webhookUrl, body, signature, authToken);

return [{ json: { ...item, firmaValida } }];

const body = $input.first().json.body || $input.first().json;
const from = body.From || body.from || '';
const text = (body.Body || body.body || '').trim();
if (!from || !text) return [{ json: { skip: true, from: '', text: '' } }];
return [{ json: { from, text, skip: false } }];

// Detectamos si el mensaje es una SELECCIÓN o un mensaje nuevo
// Formato esperado: "NUMERO | Nombre Apellido | email@algo.com" (también acepta más cortos)
const text = $json.text;
const from = $json.from;

let nombre = 'WhatsApp';
let apellido = 'User';
let email = null;
let numero = null;

// 1) Formato completo: "1 | Juan Perez | juan@mail.com"
let m = text.match(/^\s*(\d+)\s*\|\s*(.+?)\s*\|\s*(\S+@[^\s]+\.\S+)\s*$/i);
if (m) {
  numero = m[1];
  const nombreCompleto = m[2].trim();
  const partes = nombreCompleto.split(/\s+/);
  if (partes.length >= 2) { apellido = partes.pop(); nombre = partes.join(' '); }
  else { nombre = nombreCompleto; }
  email = m[3].trim().toLowerCase();
}

// 2) Formato corto: "1 | juan@mail.com"
if (!m) {
  m = text.match(/^\s*(\d+)\s*\|\s*(\S+@[^\s]+\.\S+)\s*$/i);
  if (m) { numero = m[1]; email = m[2].trim().toLowerCase(); }
}

// 3) Sin pipe: "1 juan@mail.com"
if (!m) {
  m = text.match(/^\s*(\d+)\s+(\S+@[^\s]+\.\S+)\s*$/i);
  if (m) { numero = m[1]; email = m[2].trim().toLowerCase(); }
}

if (numero && email) {
  const memory = $getWorkflowStaticData('global');
  const sesion = memory[from];
  if (!sesion || !sesion.comparativa) {
    return [{ json: { from, esSeleccion: true, error: 'No tengo una búsqueda activa tuya. Mandá un nuevo destino.' } }];
  }
  const idx = parseInt(numero, 10) - 1;
  if (idx < 0 || idx >= sesion.comparativa.length) {
    return [{ json: { from, esSeleccion: true, error: `Número inválido. Elegí entre 1 y ${sesion.comparativa.length}.` } }];
  }
  return [{ json: {
    from, esSeleccion: true, error: null,
    email, nombre, apellido,
    opcionIdx: idx,
    opcion: sesion.comparativa[idx],
    origenNombre: sesion.origenNombre,
    destinoNombre: sesion.destinoNombre,
    origenIATA: sesion.origenIATA,
    destinoIATA: sesion.destinoIATA
  } }];
}

// No es selección, es un mensaje normal para el AI Agent
return [{ json: { from, text, esSeleccion: false, error: null } }];

const raw = ($input.first().json.output || $input.first().json.text || '').trim();
const from = $('Parsear Webhook').first().json.from;

const match = raw.match(/\{[\s\S]*\}/);
if (match) {
  try {
    const j = JSON.parse(match[0]);
    if (j.origenIATA && j.destinoIATA && j.fechaIda && j.fechaVuelta
        && /^\d{4}-\d{2}-\d{2}$/.test(j.fechaIda)
        && /^\d{4}-\d{2}-\d{2}$/.test(j.fechaVuelta)
        && new Date(j.fechaVuelta) > new Date(j.fechaIda)) {
      return [{ json: {
        from, datosCompletos: true,
        origenNombre: j.origenNombre || j.origenIATA,
        destinoNombre: j.destinoNombre || j.destinoIATA,
        origenIATA: j.origenIATA.toUpperCase(),
        destinoIATA: j.destinoIATA.toUpperCase(),
        fechaIda: j.fechaIda, fechaVuelta: j.fechaVuelta,
        noches: Math.round((new Date(j.fechaVuelta) - new Date(j.fechaIda)) / 86400000),
        respuestaTexto: `⏳ *Buscando vuelos…*\n✈️ ${j.origenNombre || j.origenIATA} → ${j.destinoNombre || j.destinoIATA}\n📅 ${j.fechaIda} → ${j.fechaVuelta}\nComparando 3 fechas, tarda ~10 segundos 🔍`
      } }];
    }
  } catch(e) {}
}
return [{ json: { from, datosCompletos: false, respuestaTexto: raw } }];

const d = $input.first().json;

if (!d.fechaIda || !d.fechaVuelta) return [];

function sumarDias(fecha, dias) {
  const f = new Date(fecha + 'T12:00:00Z');
  f.setDate(f.getDate() + dias);
  return f.toISOString().split('T')[0];
}

// No permitir fechas pasadas o de hoy
const hoy = new Date();
hoy.setUTCHours(0, 0, 0, 0);
const manana = new Date(hoy);
manana.setDate(manana.getDate() + 1);

// Desplazamiento de las variantes alternativas, en dias. Configurable en
// n8n (Settings > Variables) para poder ajustarlo sin tocar el codigo.
const OFFSET = Math.abs(Number($vars.VARIANTE_OFFSET_DIAS ?? 3)) || 3;
const offsets = [-OFFSET, 0, OFFSET];

// FIX (auditoria M-10b): la etiqueta se deriva del offset real. Antes estaba
// fija en '-1 dia' / '+1 dia' con una comparacion (off === -1) que nunca se
// cumplia, de modo que la variante de -3 dias se rotulaba '+1 dia'.
function etiquetaDe(off) {
  if (off === 0) return '📅 Tus fechas';
  const signo = off < 0 ? '−' : '+';
  const n = Math.abs(off);
  return `💡 ${signo}${n} ${n === 1 ? 'día' : 'días'}`;
}

return offsets.map(off => {
  const ida = sumarDias(d.fechaIda, off);
  const vuelta = sumarDias(d.fechaVuelta, off);
  const noches = Math.round((new Date(vuelta) - new Date(ida)) / 86400000);

  if (new Date(ida + 'T12:00:00Z') < manana) return null;
  if (noches <= 0) return null;

  return { json: {
    esOriginal: off === 0,
    offsetDias: off,
    etiqueta: etiquetaDe(off),
    from: d.from, origenIATA: d.origenIATA, destinoIATA: d.destinoIATA,
    origenNombre: d.origenNombre, destinoNombre: d.destinoNombre,
    fechaIda: ida, fechaVuelta: vuelta, noches
  }};
}).filter(x => x !== null);

// ============================================================
// Smart Optimizer — construccion de la comparativa de vuelos
// Correcciones de auditoria aplicadas:
//   M-10  se elimina el respaldo posicional de getTop(): una variante sin
//         coincidencia exacta de fecha se descarta en vez de tomar el precio
//         de otra fecha. Idem en el bloque de respaldo.
//   M-10b manejo de excepciones en todo el nodo.
//   M-9   el almacen de estado caduca; antes crecia sin limite y retenia el
//         identificador telefonico de forma indefinida (Ley 25.326).
//   M-11  el umbral de ahorro deja de estar fijo en el codigo.
// ============================================================

// --- Parametros de negocio (n8n > Settings > Variables) ---
const UMBRAL_AHORRO = Number($vars.UMBRAL_AHORRO_PCT ?? 0.10);   // M-11
const MEMORIA_TTL_H = Number($vars.MEMORIA_TTL_HORAS ?? 24);     // M-9
const MAX_OPCIONES_PRINCIPALES = 3;

try {

const vuelos = $json.vuelos || [];
const variantes = $('Generar 3 Fechas').all();

if (!variantes.length) {
  return [{ json: { from: $json.from, mensaje: '😕 No pude interpretar las fechas del viaje. ¿Me las repetís?', hayOferta: false } }];
}

const v0 = variantes[0].json;
const { from, origenNombre, destinoNombre, origenIATA, destinoIATA } = v0;

function escalasTexto(flight) {
  const cant = Array.isArray(flight.flights) ? flight.flights.length - 1 : 0;
  if (cant === 0) return 'Directo ✅';
  const base = cant === 1 ? '1 escala' : `${cant} escalas`;
  if (Array.isArray(flight.layovers) && flight.layovers.length > 0) {
    return base + ': ' + flight.layovers.map(l => l.airport_code).join(' → ');
  }
  return base;
}

function formatHora(timeStr) {
  if (!timeStr) return '';
  const parts = String(timeStr).split(' ');
  return parts.length >= 2 ? parts[1] + (parts[2] ? ' ' + parts[2] : '') : timeStr;
}

const varOriginal = variantes.find(x => x.json.esOriginal)?.json;
const varsAlter = variantes.filter(x => !x.json.esOriginal).map(x => x.json);

// --- M-10: SOLO coincidencia exacta de fecha. Sin respaldo posicional. ---
// Si la API devuelve los resultados desordenados o con elementos ausentes, el
// acceso por indice asignaba el precio de una fecha a otra sin señal de error.
// En un motor de cotizacion comercial eso produce cotizaciones erroneas.
const variantesSinResultado = [];

function getTop(variante) {
  if (!variante) return null;
  const res = vuelos.find(r => {
    const fechaRes = r?.outbound_date || r?.fechaIda;
    return fechaRes && fechaRes === variante.fechaIda;
  });
  if (!res) {
    variantesSinResultado.push(variante.fechaIda);
    return null;
  }
  const top = res?.data?.itineraries?.topFlights;
  return Array.isArray(top) ? top : null;
}

function filaDe(f, v, tipo, etiqueta) {
  return {
    tipo,
    etiqueta,
    fechaIda: v.fechaIda,
    fechaVuelta: v.fechaVuelta,
    noches: v.noches,
    precio: f.price,
    aerolinea: f.flights?.[0]?.airline || 'Aerolínea',
    escalas: escalasTexto(f),
    horaSalida: formatHora(f.departure_time),
    horaLlegada: formatHora(f.arrival_time),
    duracion: f.duration?.text || ''
  };
}

let comp = [];

// 1) Hasta 3 opciones en la fecha pedida por el cliente
const topOriginal = getTop(varOriginal);
if (Array.isArray(topOriginal)) {
  topOriginal.slice(0, MAX_OPCIONES_PRINCIPALES).forEach(f => {
    if (!f?.price) return;
    comp.push(filaDe(f, varOriginal, 'principal', '📅 Tus fechas'));
  });
}

// 2) Precio minimo de la fecha original
const minPrincipal = comp.length ? Math.min(...comp.map(o => o.precio)) : Infinity;

// 3) Fechas alternativas solo si el ahorro supera el umbral
varsAlter.forEach(v => {
  const top = getTop(v);
  if (!Array.isArray(top) || !top.length || !top[0]?.price) return;
  const f = top[0];
  if (!isFinite(minPrincipal)) return;          // sin base de comparacion
  const ahorroPct = (minPrincipal - f.price) / minPrincipal;
  if (ahorroPct >= UMBRAL_AHORRO) {
    comp.push(filaDe(f, v, 'ahorro', `💡 Ahorrás ${Math.round(ahorroPct * 100)}% — ${v.etiqueta}`));
  }
});

// 4) Respaldo: si no hubo resultados en la fecha original, mostrar las
//    alternativas que si tengan resultado. M-10: emparejadas por fecha, no
//    por posicion.
if (!comp.length) {
  varsAlter.forEach(v => {
    const top = getTop(v);
    if (!Array.isArray(top) || !top.length || !top[0]?.price) return;
    comp.push(filaDe(top[0], v, 'principal', v.etiqueta));
  });
}

if (!comp.length) {
  const todosFallaron = vuelos.length > 0 && vuelos.every(v => v && typeof v.error !== 'undefined');
  if (todosFallaron) {
    return [{ json: { from, mensaje: `😕 Estamos con demoras para buscar vuelos ${origenIATA}→${destinoIATA} en este momento. Probá de nuevo en unos minutos 🙏`, hayOferta: false } }];
  }
  return [{ json: { from, mensaje: `😕 No encontré vuelos ${origenIATA}→${destinoIATA}. Probá otras fechas.`, hayOferta: false } }];
}

// Marcar el mas barato
const minTotal = Math.min(...comp.map(o => o.precio));
comp.forEach(o => o.esMasBarata = o.precio === minTotal);

// --- M-9: almacen de estado con caducidad ---
// El estado se indexa por el identificador de WhatsApp del cliente, que es un
// dato personal. Se purgan las entradas vencidas en cada ejecucion para acotar
// tanto el crecimiento del estado como el periodo de retencion.
const memory = $getWorkflowStaticData('global');
const TTL_MS = MEMORIA_TTL_H * 3600 * 1000;
const ahora = Date.now();
for (const k of Object.keys(memory)) {
  const ts = memory[k]?.ts;
  if (!ts || (ahora - ts) > TTL_MS) delete memory[k];
}
memory[from] = { comparativa: comp, origenNombre, destinoNombre, origenIATA, destinoIATA, ts: ahora };

// Armar mensaje
let m = `🔍 *COMPARATIVA DE VUELOS — STG*\n✈️ *${origenNombre} → ${destinoNombre}*\n━━━━━━━━━━━━━━━━━━━━\n\n`;
comp.forEach((o, i) => {
  const star = o.esMasBarata ? ' 🏆 *MEJOR PRECIO*' : '';
  m += `*${i+1}. ${o.etiqueta}*${star}\n💰 *USD ${o.precio}* | ${o.escalas}\n🏢 ${o.aerolinea}\n📅 ${o.fechaIda} → ${o.fechaVuelta} (${o.noches}n)\n🕐 ${o.horaSalida} → ${o.horaLlegada} (${o.duracion})\n────────────────────\n`;
});
if (variantesSinResultado.length) {
  m += `\n_(Sin disponibilidad para: ${variantesSinResultado.join(', ')})_\n`;
}
m += `\n📝 *Para reservar, respondé con:*\n\`NUMERO | Nombre Apellido | tu@email.com\`\n\n_Ejemplo:_ \`1 | Juan Perez | juan@mail.com\``;

return [{ json: { from, mensaje: m, hayOferta: true } }];

} catch (e) {
  // M-10b: ante un cambio de forma en la respuesta del proveedor tarifario,
  // el flujo degrada con un mensaje util en vez de romperse en silencio.
  console.error('Smart Optimizer:', e && e.message, e && e.stack);
  return [{ json: {
    from: $json.from,
    mensaje: '😕 Tuvimos un problema al armar la comparativa. Ya lo estamos viendo — probá de nuevo en unos minutos 🙏',
    hayOferta: false,
    error: String(e && e.message || e)
  } }];
}

const d = $json;

if (d.error) return [{ json: { from: d.from, msgFinal: '❌ ' + d.error, ok: false } }];

const opt = d.opcion;
const BASE = 'http://localhost:3000/api';
// Fase S6: x-api-key tomada de una variable de n8n (Settings > Variables),
// nunca hardcodeada en este JSON exportado.
const API_KEY = $vars.N8N_API_KEY;

async function httpRequest(method, path, body) {
  return await this.helpers.httpRequest({
    method,
    url: BASE + path,
    body,
    json: true,
    headers: { 'x-api-key': API_KEY },
  });
}

try {
  // 1) Buscar o crear cliente (filtro server-side por email — Fase S7, ya no baja toda la tabla)
  const clientesEncontrados = await httpRequest.call(this, 'GET', '/clientes?email=' + encodeURIComponent(d.email));
  let cliente = Array.isArray(clientesEncontrados) ? clientesEncontrados[0] : null;
  if (!cliente) {
    cliente = await httpRequest.call(this, 'POST', '/clientes', {
      nombre: d.nombre || 'WhatsApp',
      apellido: d.apellido || 'User',
      email: d.email,
      telefono: d.from.replace('whatsapp:', '')
    });
  }

  // 2) Buscar destinos por IATA
  const [origs, dests] = await Promise.all([
    httpRequest.call(this, 'GET', '/destinos?iata=' + d.origenIATA),
    httpRequest.call(this, 'GET', '/destinos?iata=' + d.destinoIATA)
  ]);
  const origenId = origs[0]?.id;
  const destinoId = dests[0]?.id;
  if (!origenId || !destinoId) throw new Error('Destino no encontrado en la DB');

  // 3) Crear viaje
  const viaje = await httpRequest.call(this, 'POST', '/viajes', {
    origenId, destinoId,
    tieneEscalas: !/Directo/.test(opt.escalas),
    descripcion: `${d.origenIATA} → ${d.destinoIATA} (${opt.aerolinea})`,
    tramos: [
      { origenId, destinoId, orden: 1, aerolinea: opt.aerolinea, horaSalida: opt.fechaIda + 'T08:00:00Z', horaLlegada: opt.fechaIda + 'T20:00:00Z', completo: false },
      { origenId: destinoId, destinoId: origenId, orden: 2, aerolinea: opt.aerolinea, horaSalida: opt.fechaVuelta + 'T08:00:00Z', horaLlegada: opt.fechaVuelta + 'T20:00:00Z', completo: false }
    ]
  });

  // 4) Crear cotización
  const cot = await httpRequest.call(this, 'POST', '/cotizaciones', {
    viajeId: viaje.id, clienteId: cliente.id,
    fechaVencimiento: new Date(Date.now() + 7 * 86400000).toISOString(),
    moneda: 'USD',
    precioIda: Math.round(opt.precio * 0.5),
    precioVuelta: Math.round(opt.precio * 0.5),
    precioIdaYVuelta: opt.precio,
    impuestos: Math.round(opt.precio * 0.21),
    observaciones: `Bot WhatsApp — ${opt.aerolinea} — ${opt.escalas}`
  });

  const msgFinal = `✅ *¡Cotización lista!*\n\n📋 Número: \`${cot.numeroCotizacion}\`\n✈️ ${d.origenNombre} (${d.origenIATA}) → ${d.destinoNombre} (${d.destinoIATA})\n📅 Ida: ${opt.fechaIda}  |  Vuelta: ${opt.fechaVuelta}\n🏢 ${opt.aerolinea}  •  ${opt.escalas}\n\n💰 Vuelo: USD ${opt.precio}\n💵 Impuestos (21%): USD ${Math.round(opt.precio * 0.21)}\n*TOTAL: USD ${Math.round(opt.precio * 1.21)}*\n\n📌 Válida por 7 días. También te llega el detalle a *${d.email}* 📧\nUn asesor te contacta en breve para confirmar y coordinar el pago. 👋\n\n_Para otra consulta, mandá "hola"._`;

  return [{ json: {
    from: d.from, ok: true, msgFinal,
    email: d.email,
    numeroCotizacion: cot.numeroCotizacion,
    origenNombre: d.origenNombre, destinoNombre: d.destinoNombre,
    origenIATA: d.origenIATA, destinoIATA: d.destinoIATA,
    fechaIda: opt.fechaIda, fechaVuelta: opt.fechaVuelta,
    aerolinea: opt.aerolinea, escalas: opt.escalas,
    precio: opt.precio, impuestos: Math.round(opt.precio * 0.21),
    total: Math.round(opt.precio * 1.21)
  } }];

} catch(e) {
  return [{ json: { from: d.from, ok: false, msgFinal: '⚠️ Error creando cotización: ' + e.message } }];
}
